package vn.iotstar.config; import lombok.RequiredArgsConstructor; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain; import vn.iotstar.security.CustomUserDetailsService;
@Configuration @EnableMethodSecurity @RequiredArgsConstructor public class SecurityConfig{final CustomUserDetailsService service; @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();} @Bean SecurityFilterChain securityFilterChain(HttpSecurity h)throws Exception{h.userDetailsService(service).authorizeHttpRequests(a->a.requestMatchers("/","/login","/register","/verify-otp","/resend-otp","/forgot-password","/reset-password","/css/**","/images/**","/error").permitAll().requestMatchers("/admin/**","/users/**","/categories/**").hasRole("ADMIN").anyRequest().authenticated()).formLogin(f->f.loginPage("/login").loginProcessingUrl("/login").usernameParameter("username").passwordParameter("password").defaultSuccessUrl("/",true).failureUrl("/login?error=true").permitAll()).logout(l->l.logoutUrl("/logout").logoutSuccessUrl("/login?logout=true").invalidateHttpSession(true).deleteCookies("JSESSIONID").permitAll()).exceptionHandling(e->e.accessDeniedPage("/access-denied"));return h.build();}}
